// min-heap: smallest on top
int kthLargest(vector<int>& a, int k) {
    priority_queue<int, vector<int>, greater<>> h;
    for (int x : a) {
        h.push(x);
        if ((int)h.size() > k) h.pop();
    }
    return h.top();
}

struct Node { int val; Node* next; };
Node* mergeK(vector<Node*>& lists) {
    auto cmp = [](Node* a, Node* b) { return a->val > b->val; };
    priority_queue<Node*, vector<Node*>, decltype(cmp)> h(cmp);
    for (Node* l : lists) if (l) h.push(l);
    Node dummy{0, nullptr}, *tail = &dummy;
    while (!h.empty()) {
        Node* n = h.top(); h.pop();
        tail->next = n; tail = n;
        if (n->next) h.push(n->next);
    }
    return dummy.next;
}
